#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m14-expose-shelf pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m14-expose-shelf
CHECKS="db-service web-service db-endpoints web-endpoints"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m14-expose-shelf
checks:
  - id: db-service
    describe: The Service shelf-db is a ClusterIP Service on port 5432
    kubectl:
      - get
      - service
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.spec.type}/{.spec.ports[0].port}/{.spec.ports[0].targetPort}
    expect:
      matches: ^ClusterIP/5432/(5432|postgres)$
    hint: "Create the Service from `expose-shelf/shelf-db-service.yaml`: under `ports`, add an entry with `port: 5432`. The database listens on 5432, so the target port is the same, and you may leave `targetPort` out."
  - id: web-service
    describe: The Service shelf-web is a ClusterIP Service on port 80, sending to the port 8080 of the web Pod
    kubectl:
      - get
      - service
      - shelf-web
      - -n
      - shelf
      - -o
      - jsonpath={.spec.type}/{.spec.ports[0].port}/{.spec.ports[0].targetPort}
    expect:
      matches: ^ClusterIP/80/(8080|http)$
    hint: "In `expose-shelf/shelf-web-service.yaml`, add an entry under `ports` with `port: 80` and `targetPort: 8080`. Clients use port 80, and the web server listens on 8080."
  - id: db-endpoints
    describe: The EndpointSlice of shelf-db lists one ready endpoint
    kubectl:
      - get
      - endpointslices
      - -n
      - shelf
      - -l
      - kubernetes.io/service-name=shelf-db
      - -o
      - jsonpath={.items[*].endpoints[*].conditions.ready}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "true"
    hint: "Run `kubectl get endpointslices --namespace shelf`. An empty list means that the Service selects no ready Pod: compare the selector with the labels in `kubectl get pods --namespace shelf --show-labels`. The first start pulls the database image, which can take a minute."
  - id: web-endpoints
    describe: The EndpointSlice of shelf-web lists one ready endpoint
    kubectl:
      - get
      - endpointslices
      - -n
      - shelf
      - -l
      - kubernetes.io/service-name=shelf-web
      - -o
      - jsonpath={.items[*].endpoints[*].conditions.ready}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "true"
    hint: Apply `expose-shelf/shelf-web-service.yaml` once it has its ports. Its selector matches the label of the web Pod.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
